// A user record is a real prompt only if it carries human text: not a tool
// result, not meta, not a bare system-reminder injection.
function userPrompt(o) {
  if (o.isMeta) return null;
  const c = o.message && o.message.content;
  let text = "";
  if (typeof c === "string") text = c;
  else if (Array.isArray(c)) {
    if (c.some((b) => b && b.type === "tool_result")) return null;
    text = c.filter((b) => b && b.type === "text").map((b) => b.text).join("\n");
